-- Verificar AMERICAN PIROTECNIA na inadimplência
SELECT id, cliente, valorLiquido, valorRecebidoLiquido, LEFT(vencimentoData,10) as venc, tipo FROM accounts_receivable 
WHERE UPPER(cliente) LIKE '%AMERICAN%' AND estado = 'EMITIDO' AND LEFT(vencimentoData,10) = '2026-05-11';

-- Verificar FLAVIO JOSE na inadimplência  
SELECT id, cliente, valorLiquido, valorRecebidoLiquido, LEFT(vencimentoData,10) as venc, tipo FROM accounts_receivable 
WHERE UPPER(cliente) LIKE '%FLAVIO JOSE%' AND estado = 'EMITIDO';

-- Verificar FOGOS BEIJA FLOR
SELECT id, cliente, valorLiquido, valorRecebidoLiquido, LEFT(vencimentoData,10) as venc, tipo FROM accounts_receivable 
WHERE UPPER(cliente) LIKE '%BEIJA FLOR%' AND estado = 'EMITIDO';

